INSERT INTO brands (name,slug) VALUES ('Apple','apple'),('Samsung','samsung'),('ASUS','asus'),('Lenovo','lenovo'),('Dell','dell'),('HP','hp'),('Proline','proline'),('Sony','sony'),('Anker','anker') ON CONFLICT (slug) DO NOTHING;
INSERT INTO categories (name,slug) VALUES ('Smartphones','smartphones'),('Ordinateurs','ordinaters'),('Tablettes','tablettes'),('Accessoires','accessoires') ON CONFLICT (slug) DO NOTHING;
INSERT INTO products (brand_id,category_id,name,slug,description,status,is_featured) SELECT b.id,c.id,v.name,v.slug,v.description,'draft',v.featured FROM (VALUES ('Apple','Smartphones','iPhone 17 Pro','iphone-17-pro','Smartphone Apple A19 Pro, écran OLED 6,3 pouces, stockage 256 Go.',true),('Samsung','Smartphones','Galaxy S25 Ultra','galaxy-s25-ultra','Smartphone Galaxy AI, Snapdragon 8 Elite, 12 Go RAM et 256 Go.',true),('Apple','Ordinateurs','MacBook Air 13 M4','macbook-air-m4','Ordinateur Apple M4, 16 Go RAM et 256 Go SSD.',true),('ASUS','Ordinateurs','ASUS Zenbook 14 OLED','asus-zenbook-14','Intel Core Ultra 7, écran OLED 14 pouces, 16 Go RAM et 1 To SSD.',true),('Apple','Tablettes','iPad Pro 11 M4','ipad-pro-m4','Tablette Apple M4, écran Ultra Retina XDR et 256 Go.',false),('Samsung','Tablettes','Galaxy Tab S10 Ultra','galaxy-tab-s10-ultra','Tablette Samsung 14,6 pouces, 12 Go RAM et 256 Go.',false),('Apple','Accessoires','AirPods Pro 2','airpods-pro-2','Écouteurs sans fil avec réduction active du bruit.',false),('Sony','Accessoires','Sony WH-1000XM5','sony-xm5','Casque sans fil avec réduction de bruit.',false),('Proline','Ordinateurs','Proline Business 15 Core i5','proline-business-i5','Intel Core i5, 8 Go RAM et 512 Go SSD.',false),('ASUS','Ordinateurs','ASUS Vivobook 15','asus-vivobook-15','Intel Core i5 13e génération, 16 Go RAM et 512 Go SSD.',false),('Lenovo','Ordinateurs','Lenovo ThinkPad E14','lenovo-thinkpad-e14','Intel Core i7, écran 14 pouces, 16 Go RAM et 512 Go SSD.',false),('Dell','Ordinateurs','Dell XPS 13','dell-xps-13','Intel Core Ultra 7, écran 13,4 pouces, 16 Go RAM et 512 Go SSD.',false),('HP','Ordinateurs','HP Victus 16','hp-victus-16','Intel Core i5, RTX 4050, 16 Go RAM et 512 Go SSD.',false),('Apple','Ordinateurs','MacBook Pro 14 M4','macbook-pro-14-m4','Apple M4, écran Liquid Retina XDR, 16 Go RAM et 512 Go SSD.',false),('Samsung','Smartphones','Galaxy S25','galaxy-s25','Snapdragon 8 Elite, écran AMOLED 6,2 pouces, 12 Go RAM et 256 Go.',false),('Apple','Smartphones','iPhone 16','iphone-16','Puce A18, écran OLED 6,1 pouces et stockage 128 Go.',false),('Apple','Accessoires','AirPods 4','airpods-4','Écouteurs sans fil Apple avec audio spatial et boîtier USB-C.',false),('Anker','Accessoires','Batterie externe Anker 20 000 mAh','anker-powerbank','Batterie externe USB-C avec charge rapide.',false)) AS v(brand_name,category_name,name,slug,description,featured) JOIN brands b ON b.slug=lower(v.brand_name) JOIN categories c ON c.name=v.category_name ON CONFLICT (slug) DO NOTHING;
INSERT INTO product_variants (product_id,sku,label,price,currency,attributes) SELECT p.id,v.sku,v.label,v.price,'USD','{}'::jsonb FROM (VALUES ('iphone-17-pro','CT-IPHONE-17-PRO','Configuration de base',1300),('galaxy-s25-ultra','CT-GALAXY-S25-ULTRA','Configuration de base',1250),('macbook-air-m4','CT-MACBOOK-AIR-M4','Configuration de base',1050),('asus-zenbook-14','CT-ASUS-ZENBOOK-14','Configuration de base',1200),('ipad-pro-m4','CT-IPAD-PRO-M4','Configuration de base',1280),('galaxy-tab-s10-ultra','CT-GALAXY-TAB-S10-ULTRA','Configuration de base',1080),('airpods-pro-2','CT-AIRPODS-PRO-2','Configuration de base',250),('sony-xm5','CT-SONY-XM5','Configuration de base',350),('proline-business-i5','CT-PROLINE-BUSINESS-I5','Configuration de base',600),('asus-vivobook-15','CT-ASUS-VIVOBOOK-15','Configuration de base',650),('lenovo-thinkpad-e14','CT-LENOVO-THINKPAD-E14','Configuration de base',950),('dell-xps-13','CT-DELL-XPS-13','Configuration de base',1500),('hp-victus-16','CT-HP-VICTUS-16','Configuration de base',1000),('macbook-pro-14-m4','CT-MACBOOK-PRO-14-M4','Configuration de base',1700),('galaxy-s25','CT-GALAXY-S25','Configuration de base',800),('iphone-16','CT-IPHONE-16','Configuration de base',800),('airpods-4','CT-AIRPODS-4','Configuration de base',160),('anker-powerbank','CT-ANKER-POWERBANK','Configuration de base',60)) AS v(slug,sku,label,price) JOIN products p ON p.slug=v.slug ON CONFLICT (sku) DO NOTHING;
